import React from 'react';
import { useTranslation } from 'react-i18next';
import { FaEllipsisH } from 'react-icons/fa';
import { Menu } from '~/components/ui/menu';
import { Button } from '~/components/ui/button';
import { Icon } from '~/components/ui/icon';
import { HStack } from 'styled-system/jsx';
import { Link } from '~/components/ui/link';

interface MoreMenuProps {
  items: { href: string; icon: React.ElementType; labelKey: string; isExternal?: boolean }[];
}

export function MoreMenu({ items }: MoreMenuProps) {
  const { t, i18n } = useTranslation();

  return (
    <Menu.Root>
      <Menu.Trigger asChild>
        <Button variant="ghost" size="lg" aria-label={t('navigation.more')}>
          <Icon>
            <FaEllipsisH />
          </Icon>
        </Button>
      </Menu.Trigger>
      <Menu.Positioner>
        <Menu.Content>
          <Menu.ItemGroup>
            {items.map((item) => (
              <Menu.Item key={item.href} value={item.href}>
                {item.isExternal ? (
                  <Link href={item.href} target="_blank" rel="noopener noreferrer">
                    <HStack gap="2">
                      <Icon>
                        <item.icon />
                      </Icon>
                      {t(item.labelKey)}
                    </HStack>
                  </Link>
                ) : (
                  <Link href={item.href}>
                    <HStack gap="2">
                      <Icon>
                        <item.icon />
                      </Icon>
                      {t(item.labelKey)}
                    </HStack>
                  </Link>
                )}
              </Menu.Item>
            ))}
            <Menu.Item value="language-toggle" asChild>
              <HStack
                onClick={() => {
                  const newLang = i18n.language === 'en' ? 'ja' : 'en';
                  void i18n.changeLanguage(newLang);
                }}
                gap="2"
              >
                {t('navigation.switch_language', {
                  language: i18n.language === 'en' ? '日本語' : 'English'
                })}
              </HStack>
            </Menu.Item>
          </Menu.ItemGroup>
        </Menu.Content>
      </Menu.Positioner>
    </Menu.Root>
  );
}
